import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DQbZ8cc1.js";const m=JSON.parse('{"title":"Service Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/installation/server/install.md","filePath":"en/docs/installation/server/install.md"}'),l={name:"en/docs/installation/server/install.md"};function n(o,e,r,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="service-deployment" tabindex="-1">Service Deployment <a class="header-anchor" href="#service-deployment" aria-label="Permalink to “Service Deployment”">​</a></h1><p>This document follows the current all-in-one deployment mode: one <code>bbs-go</code> process serves site, admin, and API.</p><h2 id="_1-prerequisites" tabindex="-1">1. Prerequisites <a class="header-anchor" href="#_1-prerequisites" aria-label="Permalink to “1. Prerequisites”">​</a></h2><ul><li>Database: <ul><li>MySQL 8+ recommended for production</li><li>SQLite available for local trial</li></ul></li></ul><h2 id="_2-get-and-prepare" tabindex="-1">2. Get and Prepare <a class="header-anchor" href="#_2-get-and-prepare" aria-label="Permalink to “2. Get and Prepare”">​</a></h2><p>Using release packages is recommended:</p><ol><li>Download the package for your platform from Releases</li><li>Extract package</li><li>In the extracted directory, ensure <code>bbs-go</code>, <code>site/</code>, <code>admin/</code>, <code>res/</code>, and <code>locales/</code> exist</li></ol><h2 id="_3-start-service" tabindex="-1">3. Start Service <a class="header-anchor" href="#_3-start-service" aria-label="Permalink to “3. Start Service”">​</a></h2><p>Run in release package directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux/macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bbs-go</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbs-go.exe</span></span></code></pre></div><p>Default port: <code>8082</code>.</p><h2 id="_4-first-time-installation" tabindex="-1">4. First-Time Installation <a class="header-anchor" href="#_4-first-time-installation" aria-label="Permalink to “4. First-Time Installation”">​</a></h2><p>When not installed, open:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;host&gt;:8082/install</span></span></code></pre></div><p>The installer supports:</p><ul><li>Language: <code>en-US</code> / <code>zh-CN</code></li><li>Database: MySQL / SQLite</li><li>Site info and admin account initialization</li></ul><p>After success, <code>bbs-go.yaml</code> is written automatically and migrations are initialized.</p><h2 id="_5-endpoints" tabindex="-1">5. Endpoints <a class="header-anchor" href="#_5-endpoints" aria-label="Permalink to “5. Endpoints”">​</a></h2><ul><li>Site: <code>http://&lt;host&gt;:8082/</code></li><li>Admin: <code>http://&lt;host&gt;:8082/admin</code></li><li>API: <code>http://&lt;host&gt;:8082/api/*</code></li></ul><h2 id="_6-production-recommendations" tabindex="-1">6. Production Recommendations <a class="header-anchor" href="#_6-production-recommendations" aria-label="Permalink to “6. Production Recommendations”">​</a></h2><ul><li>Use MySQL in production</li><li>Put Nginx/Caddy in front for HTTPS</li><li>Backup database and uploaded assets regularly</li><li>Use systemd/supervisor/container platform to manage process lifecycle</li></ul><h2 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to “7. Troubleshooting”">​</a></h2><h3 id="port-already-in-use" tabindex="-1">Port already in use <a class="header-anchor" href="#port-already-in-use" aria-label="Permalink to “Port already in use”">​</a></h3><p>Change <code>Port</code> in <code>bbs-go.yaml</code> or free the occupied port.</p><h3 id="cannot-access-installer" tabindex="-1">Cannot access installer <a class="header-anchor" href="#cannot-access-installer" aria-label="Permalink to “Cannot access installer”">​</a></h3><p>Make sure the service is running and open <code>/install</code>; installed instances redirect to <code>/</code>.</p><h3 id="sqlite-notes" tabindex="-1">SQLite notes <a class="header-anchor" href="#sqlite-notes" aria-label="Permalink to “SQLite notes”">​</a></h3><p>SQLite is good for local trial/small usage; MySQL is recommended for production.</p><h2 id="_8-related-docs" tabindex="-1">8. Related Docs <a class="header-anchor" href="#_8-related-docs" aria-label="Permalink to “8. Related Docs”">​</a></h2><ul><li><a href="./google-login.html">Google Login Configuration</a></li></ul>`,30)])])}const u=a(l,[["render",n]]);export{m as __pageData,u as default};
